mapper.sql:
p.activo = TRUE

    AND p.operacion = #{criteria.operacion}


    AND p.tipo_propiedad = #{criteria.tipoPropiedad}


    AND p.comuna_id = #{criteria.comunaId}


    AND p.precio_uf >= #{criteria.precioMinUf}


    AND p.precio_uf <= #{criteria.precioMaxUf}


    AND p.dormitorios >= #{criteria.dormitoriosMin}


    AND p.banos >= #{criteria.banosMin}


    AND p.subsidio_ds19 = TRUE


    AND p.subsidio_ds1 = TRUE



    AND EXISTS (
        SELECT 1 
        FROM estacion_metro em 
        WHERE ST_DWithin(
            p.ubicacion, 
            em.ubicacion, 
            COALESCE(#{criteria.metroDistanciaMaximaMts}, 800)
        ) 
        AND em.activo = TRUE
    )
